RockCommerce.component("rcproduct",{amount:1,amountInput:!1,maxamount:1,minamount:1,variationString:"",price:0,money:null,init(){RockCommerce.addComponent(this);this.money=new RockMoney(this.$el.getAttribute("rc-price"));this.minamount=parseInt(this.$rcattr("rc-minamount")||RockCommerce.config.minamount);this.initAmount();this.$watch("amount",this.update.bind(this));this.maxamount=parseInt(this.$rcattr("rc-maxamount")||RockCommerce.config.maxamount);this.update()},get addToCartUrl(){return"tbd"},getVariation(id){const selector=`[x-data=rcvariation][rc-pid="${id}"]`;const varEl=this.$root.querySelector(selector);return RockCommerce.getComponent(varEl)},getVariationString(withAmount){let obj={};if(withAmount!==!1)obj.amount=this.amount;this.variations.forEach((variation)=>{obj[variation.$rcpid]=variation.optionsString});let str="#";Object.keys(obj).forEach((key)=>{str+=`&${key}=${obj[key]}`});if(this.$rcattr("rc-updateUrl")){let url=new URL(window.location);url.hash=str;history.replaceState(null,"",url)}
this.variationString=str;return str},initAmount(){this.amountInput=this.$el.querySelector("[x-model=amount]");this.amount=parseInt(this.amountInput.value||this.minamount);if(!this.amountInput)return;this.amountInput.addEventListener("focus",(e)=>{e.target.select()})},minus(){if(this.amount-1<this.minamount)return(this.amount=this.minamount);if(this.amount-1>this.maxamount)return(this.amount=this.maxamount);this.amount--},plus(){if(this.amount+1>this.maxamount)return(this.amount=this.maxamount);if(this.amount+1<this.minamount)return(this.amount=this.minamount);this.amount++},update(){RockCommerce.throttle(()=>{let amount=this.amount;if(amount>this.maxamount)amount=this.maxamount;else if(amount<this.minamount)amount=this.minamount;this.amount=amount;let money=this.money;money=RockCommerce.trigger("rcproduct:priceAddVariations",money,(money)=>{this.variations.forEach((variation)=>{if(typeof variation=="undefined")return;variation.options(!0).forEach((option)=>{money=money.plus(option.money.float())})});return money});money=RockCommerce.trigger("rcproduct:priceTotal",money,(money)=>{return money.times(this.amount)});this.price=money.format();this.getVariationString()},0)},get variations(){return Array.from(this.$root.querySelectorAll("[x-data=rcvariation]")).map((el)=>{return RockCommerce.getComponent(el)})},})